data class MessageRecord(val id: String, val channel: String, val at: Instant, val body: String)
private val tap = Channel<MessageRecord>(capacity = 10_000)
fun offer(r: MessageRecord) {
    tap.trySend(r).onFailure { drops.increment() }    // never suspends, never throws
}
fun CoroutineScope.storeWriter(db: Database) = launch(Dispatchers.IO) {
    for (r in tap) db.transaction { insertRecord(r) } // single writer, one connection
}
